/* eslint-disable react/require-default-props */
import React from 'react';
import { styled } from '@hexa-ui/theme';
import { GridContainerCSS, GridItemCSS } from './Grid.styles';
import { ContainerProps, ItemProps, ItemSizes } from './Grid.types';

const StyledGridContainer = styled('div', GridContainerCSS);
const StyledGridItem = styled('div', GridItemCSS);

function calcSize(bp?: ItemSizes) {
  return bp ? (bp === 'auto' ? 'auto' : `${(bp / 12) * 100}%`) : undefined;
}

const Item = ({ xs = 'auto', sm, md, lg, xl, children, ...props }: ItemProps): JSX.Element => (
  <StyledGridItem
    css={{
      flexBasis: `${calcSize(xs)}`,
      '@tablet': {
        flexBasis: `${calcSize(sm)}`,
      },
      '@desktopSmall': {
        flexBasis: `${calcSize(md)}`,
      },
      '@desktopLarge': {
        flexBasis: `${calcSize(lg)}`,
      },
      '@desktopXlarge': {
        flexBasis: `${calcSize(xl)}`,
      },
    }}
    {...props}
  >
    {children}
  </StyledGridItem>
);

const Container = ({
  type = 'contained',
  sidebar = false,
  children,
  ...props
}: ContainerProps): JSX.Element => (
  <StyledGridContainer
    css={{
      ...(sidebar &&
        type === 'fluid' && {
          '@desktopSmall': { paddingLeft: '5rem' },
        }),
    }}
    type={type}
    {...props}
  >
    {children}
  </StyledGridContainer>
);

export { Container, Item };
